package com.bank.comp.service;

import com.bank.comp.model.Employee;
import com.bank.comp.repository.EmployeeRepository;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.Logger;
import java.util.stream.Collectors;

public class CompensationService {
    private static final Logger log = Logger.getLogger(CompensationService.class.getName());
    private final EmployeeRepository repo;
    public CompensationService(EmployeeRepository repo) { this.repo = repo; }

    // SELECT city, MAX(salary) GROUP BY city
    public Map<String, BigDecimal> maxSalaryPerCity() {
        Map<String, BigDecimal> max = new TreeMap<>();
        for (Employee e : repo.findAll()) {
            max.merge(e.getCity(), e.getSalary(), (a, b) -> a.max(b));
        }
        return max;
    }

    // SELECT department, SUM(salary) GROUP BY department
    public Map<String, BigDecimal> totalSalaryPerDepartment() {
        Map<String, BigDecimal> sum = new TreeMap<>();
        for (Employee e : repo.findAll()) {
            sum.merge(e.getDepartment(), e.getSalary(), BigDecimal::add);
        }
        return sum;
    }

    // DENSE_RANK() OVER (ORDER BY salary DESC) = 2  → second-highest DISTINCT salary
    public BigDecimal secondHighestSalary() {
        List<BigDecimal> distinctDesc = repo.findAll().stream()
                .map(Employee::getSalary)
                .distinct()                                  // DISTINCT salaries
                .sorted(Comparator.reverseOrder())           // ORDER BY DESC
                .collect(Collectors.toList());
        if (distinctDesc.size() < 2) {
            log.warning("No second-highest salary exists");
            return null;
        }
        return distinctDesc.get(1);                          // rank 2
    }
}
