package com.bank.comp;

import com.bank.comp.repository.EmployeeRepository;
import com.bank.comp.service.CompensationService;

public class CompensationApplication {
    public static void main(String[] args) {
        CompensationService svc = new CompensationService(new EmployeeRepository());
        System.out.println("MAX SALARY PER CITY:");
        svc.maxSalaryPerCity().forEach((c, s) -> System.out.printf("  %-8s Rs.%s%n", c, s));
        System.out.println("TOTAL SALARY PER DEPARTMENT:");
        svc.totalSalaryPerDepartment().forEach((d, s) -> System.out.printf("  %-8s Rs.%s%n", d, s));
        System.out.println("SECOND-HIGHEST SALARY: Rs." + svc.secondHighestSalary());
    }
}
